import{_ as d,o as e,c as o,a as r}from"./chunks/framework.Ld7uezS_.js";const S=JSON.parse('{"title":"知识点覆盖矩阵草案（审查/规划）","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge-coverage-matrix.md","filePath":"knowledge-coverage-matrix.md","lastUpdated":1787291594000}'),c={name:"knowledge-coverage-matrix.md"};function a(i,t,l,h,s,n){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="知识点覆盖矩阵草案-审查-规划" tabindex="-1">知识点覆盖矩阵草案（审查/规划） <a class="header-anchor" href="#知识点覆盖矩阵草案-审查-规划" aria-label="Permalink to &quot;知识点覆盖矩阵草案（审查/规划）&quot;">​</a></h1><blockquote><p>用途：审计与后续补课规划，不是现行课程内容。本文仅新增审查文件，不替代《消防设施操作员国家职业技能标准（2019年版）》、现行国家标准、设备说明书或鉴定站当批次评分表。</p><p>状态口径：<strong>已覆盖</strong>=页面有可读框架；<strong>过简</strong>=仅一句话/通用口诀，不能支撑判断或实操；<strong>缺失</strong>=当前没有可学习内容；<strong>待核验</strong>=存在时效、链接或版本风险。</p></blockquote><h2 id="p0-必须先补齐" tabindex="-1">P0：必须先补齐 <a class="header-anchor" href="#p0-必须先补齐" aria-label="Permalink to &quot;P0：必须先补齐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>职业功能/理论模块</th><th>知识点</th><th>当前页面</th><th>缺口</th><th>目标页面</th><th>题卡需求</th><th>来源状态</th><th>核验备注</th></tr></thead><tbody><tr><td>P0</td><td>设施操作/保养/维修/检测</td><td>按设备项目拆解：任务识别、对象/区域确认、前置安全、操作序列、预期显示/动作/反馈、异常分支、恢复、记录</td><td><code>/skill/02-operation</code>、<code>/skill/03-maintenance</code>、<code>/skill/04-repair</code>、<code>/skill/05-detection</code></td><td>报警、水系统和其他设施已分别新增设备级学习卡；后续转入来源、标准条目和型号差异核验</td><td>各设备项目卡及 <code>course-companion.md</code> 操作前置课</td><td>每设备至少 L1 识别、L2 程序、L3 异常/恢复各1组；先能口述位置—对象—目的—预期—恢复</td><td>职业标准有框架；设备细节待按型号/站点核验</td><td>先建立“职业标准职业功能—工作内容—技能要求—知识要求”逐条映射；不得把原创卡宣称评分表</td></tr><tr><td>P0</td><td>设施维修/检测</td><td>报警主机、探测器、手报、模块、主备电、回路/通信、泵组/水系统、风机风阀、卷帘、电梯迫降、气体灭火、应急照明分项训练</td><td><code>/skill/04-repair</code>、<code>/skill/05-detection</code>、<code>/skill/alarm-system</code></td><td>维修页已新增报警、水系统、其他设施各12个故障案例，统一覆盖信息/供电/线路通信/现场设备/逻辑配置、影响范围、临时防护、升级条件和复测记录；仍需型号与依据逐项核验</td><td><code>skill/04-repair</code>、<code>skill/05-detection</code> 分设备补卡</td><td>每类设备“故障现象→原因假设→安全隔离→处理→验证→报告”；S44-S49为对应只读场景</td><td>多数需 GB 50116/50166、GB 50261、GB 50974、GB 51251、GB 51309、GB 25201 等核验</td><td>具体按钮、阈值、允许误差不得脱离设备说明书/检测方案写死；维修权限需按授权核验</td></tr><tr><td>P0</td><td>全理论/全技能</td><td>国家职业标准四级检测维修保养方向逐条覆盖矩阵</td><td><code>index.md</code>、<code>exam-guide.md</code>、<code>skill-roadmap.md</code></td><td>只宣称“全覆盖”，没有条款/工作任务到页面、题卡的可追溯映射</td><td>本矩阵扩展为标准条目清单；后续可拆 <code>audit/standard-mapping.md</code></td><td>每个标准知识点至少1张题卡；关键技能★每项至少1张场景卡</td><td>国家职业技能标准PDF已列于 <code>/sources</code></td><td>由主理人按标准原文复核并记录版本、页码、适用方向</td></tr><tr><td>P0</td><td>理论训练</td><td>10个理论模块题卡覆盖与难度梯度</td><td><code>/training-theory</code></td><td>已为十章建立基础、辨析和综合场景入口；题量仍不等于官方题库或实际考试题量</td><td><code>/training-theory</code> 或按模块拆分题卡</td><td>后续继续均衡每章 L1/L2/L3，并按知识点补题</td><td>现有均为原创题，非官方真题</td><td>T28-T37 为每章一张 L3 综合题；训练页覆盖表已同步</td></tr><tr><td>P0</td><td>技能训练</td><td>检测维修保养方向四项职业功能题卡量与场景分布</td><td><code>/training-skill</code></td><td>当前已扩展至 S01-S49；按批次覆盖报警、水系统、其他设施、检测仪器和故障诊断；题量仍不等于官方题库和鉴定站评分覆盖</td><td><code>/training-skill</code> 或按职业功能拆卡</td><td>后续按设备、标准条目和难度补卡；保留原创题标记并维护题号索引</td><td>现有均为原创题</td><td>监控仅作基础；检测维修保养核心为操作、保养、维修、检测；题卡编号须与页面同步</td></tr><tr><td>P0</td><td>设施检测</td><td>检测仪器用途、接线、量程、精度/校准、读数和报告</td><td><code>/skill/05-detection</code>、<code>/skill/alarm-system</code>、<code>/skill/water-system</code>、<code>/skill/other-facilities</code></td><td>已建立仪器类别、使用前检查、接线/探头安全、原始记录、异常复测和报告字段；具体型号、量程和判定值仍需按依据核验</td><td>继续按系统补充型号化检测卡，不把通用框架写成固定参数</td><td>仪器选择题、读数/异常判定题、检测记录题</td><td>职业标准、现行标准、检测方案、设备说明书需逐项核验</td><td>不写脱离设备与标准的统一阈值；每项保留依据文件与版本字段</td></tr><tr><td>P0</td><td>考试流程</td><td>报名、地方公告、现场实操、评分表、补考/成绩有效期核验流程</td><td><code>/exam-guide</code></td><td>已补报考条件证据边界、材料真实性提醒、现场实操适用对象和地方公告核验要求；补考/成绩有效期仍不外推全国统一规则</td><td><code>/exam-guide</code> 的报名核验清单和 sources.md</td><td>流程判断题、考试规则易错题；不模拟未核验的全国统一参数</td><td>官方官网/地方公告需逐条核验</td><td>2024-11-19公告明确新报名考生现场实际操作；历史报名人员和补考安排仍按适用公告区分</td></tr></tbody></table><h2 id="p1-补足高频知识与来源" tabindex="-1">P1：补足高频知识与来源 <a class="header-anchor" href="#p1-补足高频知识与来源" aria-label="Permalink to &quot;P1：补足高频知识与来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>职业功能/理论模块</th><th>知识点</th><th>当前页面</th><th>缺口</th><th>目标页面</th><th>题卡需求</th><th>来源状态</th><th>核验备注</th></tr></thead><tbody><tr><td>P1</td><td>职业道德</td><td>守则、岗位责任、违规后果、交接班与报告边界</td><td><code>/theory/01-professional-ethics</code></td><td>已补职业道德、法律、制度、规程、授权的层级差异和失职/越权/误操作案例；标准原文与地方制度仍需按适用版本核验</td><td>同页持续按岗位场景补充</td><td>守则辨析、报警处置边界、违规后果题</td><td>职业标准有依据</td><td>明确事实、岗位建议、案例假设三种表述</td></tr><tr><td>P1</td><td>消防工作概述</td><td>消防组织体系、单位/岗位/部门责任、基本制度</td><td><code>/theory/02-fire-service-overview</code></td><td>已补政府、部门、单位、公民/员工责任链及发现异常后的记录—评估—维修—复测分工</td><td>同页持续补责任场景</td><td>主体责任、报告升级、检测责任辨析题</td><td>消防法现行文本待核验</td><td>现有NPC长串链接疑似失效，需替换可访问官方检索入口</td></tr><tr><td>P1</td><td>燃烧和火灾</td><td>可燃物/氧化剂分类、爆炸/爆燃、烟气危害、灭火剂禁忌</td><td><code>/theory/03-combustion-fire</code></td><td>已补三要素与四面体的关系、灭火原理对应和多种原理并用边界；爆炸性环境与专项处置仍需依据核验</td><td>同页按场景补充</td><td>A-F场景、灭火剂选择/禁忌、烟气安全题</td><td>GB/T 4968已提及，需核验现行状态</td><td>“上风/侧上风”应避免脱离现场条件的绝对化</td></tr><tr><td>P1</td><td>建筑防火</td><td>构件耐火性能、防火门窗/防火阀/挡烟垂壁、疏散指标、楼梯/避难层/车道</td><td><code>/theory/04-building-fire</code></td><td>已补核心概念和部分构件关系；防烟构造、疏散条件、救援条件仍需继续按对象—作用—识别—异常展开</td><td>同页按主题补</td><td>建筑分类、分区、疏散、设施状态辨析题</td><td>GB 55037、GB 50016适用边界待核验</td><td>明确通用规范与配套标准的现行关系，避免“GB 50016全废止”误解</td></tr><tr><td>P1</td><td>电气消防</td><td>交流/直流、三相、消防电源切换、静电/雷电、保护装置与检测</td><td><code>/theory/05-electrical-fire</code></td><td>已补故障现象—优先怀疑—岗位边界；防爆区域术语、电源切换和授权测量仍需继续展开</td><td>同页补电源与保护</td><td>公式理解、故障识别、消防电源/保护选择题</td><td>GB/T 13955、GB 50058等仅在正文提名，缺直接可查链接</td><td>所有计算示例注明不构成选型结论</td></tr><tr><td>P1</td><td>消防设施</td><td>报警系统回路/模块/控制方式；喷淋报警阀组；气体/泡沫/干粉；给水泵组；防烟排烟与其他设施</td><td><code>/theory/06-fire-facilities</code>、<code>/skill/alarm-system</code>、<code>/skill/water-system</code>、<code>/skill/other-facilities</code></td><td>已补报警、水系统和其他设施设备级学习卡；气体/泡沫/干粉仍以理论扩展和专业边界为主</td><td>同页按系统继续拆解</td><td>组件识别、信号链、系统类型、反馈/恢复、故障排查题</td><td>需 GB 50116/50166、GB 50261、GB 50974 等直接来源</td><td>末端试水、压力/时间等数值必须引用检测依据；报警设备阈值和按钮步骤按说明书/方案核验</td></tr><tr><td>P1</td><td>初起火灾处置</td><td>灭火器检查周期/报废、现场警戒与保护、场景分工</td><td><code>/theory/07-initial-fire</code></td><td>已补位置、类型、外观、部件、标识、维修/报废状态的零基础检查顺序；具体周期、报废和检验仍按产品标识、现行标准、单位制度与有资质机构核验</td><td>同页补器材检查和场景卡</td><td>灭火剂适用、器材检查、报警疏散顺序题</td><td>GB 50140/50444等待补直接链接</td><td>处置内容必须服从现场预案，不替代培训授权</td></tr><tr><td>P1</td><td>计算机基础</td><td>控制器/图形主机界面、打印/日志、权限、网络通信、备份恢复</td><td><code>/theory/08-computer</code></td><td>已补输入—处理—存储—输出信息链、文件/数据库/日志/备份区别和报警到交接案例；品牌界面和恢复操作仍需说明书核验</td><td>同页继续补控制室信息系统</td><td>日志追溯、记录完整性、故障/权限题</td><td>职业标准有基础要求，设备界面需说明书</td><td>不绑定单一品牌菜单名称</td></tr><tr><td>P1</td><td>法律法规与标准</td><td>消防法高频条款、安法义务、行政责任、维护记录周期</td><td><code>/theory/09-laws-standards</code></td><td>仅列第16/28/44/51条和标准索引</td><td>同页补条款索引及版本表</td><td>条款适用、责任主体、标准层级辨析题</td><td>现有部分正文链接待核验；标准全文入口已提供</td><td>记录每一条的法律/标准版本和核查日期</td></tr><tr><td>P1</td><td>安全生产与职业健康</td><td>PPE、锁定挂牌/验电、有限空间、高处/动火、急救、事故报告</td><td><code>/theory/10-safety-health</code></td><td>危险源和作业前中后框架有，缺专项作业要点</td><td>同页按风险补</td><td>风险识别、停止条件、隔离/监护流程题</td><td>安法与职业标准链接待核验</td><td>不把网页步骤视为现场授权或替代特种作业培训</td></tr><tr><td>P1</td><td>设施监控</td><td>控制器菜单/指示灯/打印、监管输入、交接班和值班记录</td><td><code>/skill/01-monitoring</code></td><td>四类信息和闭环已有，缺设备界面与交接班颗粒度</td><td>同页补“界面与记录”</td><td>火警/故障/监管/屏蔽分支场景题</td><td>设备说明书、单位制度、评分表待补</td><td>监控内容作为检测维修保养方向基础，不误称独立考核范围</td></tr><tr><td>P1</td><td>设施保养</td><td>GB 25201周期/项目/判定；报警、泵阀、风机、卷帘、灭火器、照明分项</td><td><code>/skill/03-maintenance</code></td><td>已补巡查、保养、检测、维修的目的、证据和边界，并保留报警、水系统、其他设施分项保养卡；周期、比例和判定仍需按依据核验</td><td>同页继续按设备细化</td><td>保养前置、安全影响、功能确认、记录题</td><td>GB 25201、产品说明书需直接链接</td><td>“外观正常”不能代替功能合格，需各设备判定依据</td></tr><tr><td>P1</td><td>设施维修</td><td>故障代码/电压电阻/通信诊断、编码、替换、复测、资质边界</td><td><code>/skill/04-repair</code></td><td>故障树为方向性建议，缺可复核诊断步骤</td><td>同页新增典型故障案例</td><td>无反馈、误报、主备电、泵不启动等L3题</td><td>设备说明书/维修规程/评分表待补</td><td>只展示授权范围内的诊断，禁止诱导带电拆装</td></tr><tr><td>P1</td><td>设施检测</td><td>各系统方法、抽检/全检、合格判定、报告、复测</td><td><code>/skill/05-detection</code>、<code>/skill/alarm-system</code>、<code>/skill/water-system</code>、<code>/skill/other-facilities</code></td><td>已补检查、测量、试验、检测、判定五个术语及证据边界；按项目的抽检范围、方法与判定仍需核验</td><td>继续按设备型号、方案和鉴定站项目拆卡</td><td>输入—显示—动作—反馈—恢复+判定依据题</td><td>现有依据入口已集中到 sources.md，具体项目仍需标准/方案/说明书核验</td><td>每张卡必须带方法、仪器、版本、异常和后续处理字段</td></tr></tbody></table><h2 id="p2-口径、导航与追溯性" tabindex="-1">P2：口径、导航与追溯性 <a class="header-anchor" href="#p2-口径、导航与追溯性" aria-label="Permalink to &quot;P2：口径、导航与追溯性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>职业功能/理论模块</th><th>知识点</th><th>当前页面</th><th>缺口</th><th>目标页面</th><th>题卡需求</th><th>来源状态</th><th>核验备注</th></tr></thead><tbody><tr><td>P2</td><td>站点总览</td><td>“理论/技能全覆盖”“5大职业功能”宣传口径</td><td><code>/index.md</code>、<code>/beginner-guide.md</code>、<code>/training-skill.md</code></td><td>已改为“理论十模块”和“检测维修保养四项核心职业功能”；监控明确为基础，不再作为本方向独立核心功能宣传</td><td><code>/index.md</code>、<code>/skill-roadmap.md</code></td><td>后续继续检查新页面是否复述“全覆盖”</td><td>职业标准已有来源</td><td>站点应使用“完整知识框架/系统学习”而非官方考试全覆盖承诺</td></tr><tr><td>P2</td><td>术语表</td><td>报警阀组、水流指示器、压力开关、末端试水、模块、稳压泵、水泵接合器、正压送风、排烟防火阀、气体灭火、静压/动压/流量、检测术语、消防电梯、广播电话、到位反馈</td><td><code>/glossary.md</code></td><td>已补水力基础、检查/测量/试验/判定/原始记录/复测、消防电梯、应急广播、消防电话等高频词；气体灭火和更多品牌术语仍需按来源逐词绑定</td><td><code>/glossary.md</code></td><td>每词1道识记/辨析题，并链接系统页</td><td>来源分散在工程标准，当前未逐词绑定</td><td>术语定义需区分法律/标准/品牌界面名称</td></tr><tr><td>P2</td><td>来源治理</td><td>各章节直接来源、标准版本、链接可访问性</td><td>各 <code>theory/*.md</code>、<code>skill/*.md</code>、<code>sources.md</code></td><td>已补 GB 50166-2019、GB 50261-2017、GB 50974-2014、GB 50444-2008 公开目录与适用范围；职业标准分项、考核大纲和部分章节直接来源仍待逐条核验</td><td><code>/sources.md</code> 与各章节参考区</td><td>每题保留 sourceType/sourceRef/verifiedAt/version</td><td>首批标准元数据已覆盖，逐条原文仍待核验</td><td>公开目录状态不能替代标准全文适用性判断；来源池不得用占位或不可查链接补位</td></tr><tr><td>P2</td><td>训练系统</td><td>模拟反馈、错题统计、阶段性检查</td><td><code>/training.md</code>、<code>/training-theory.md</code>、<code>/training-skill.md</code></td><td>只读设计诚实但无法发现薄弱点，训练题量也不足</td><td>规划文件/后续训练组件</td><td>题卡增加知识点ID，后续支持按ID汇总</td><td>当前全部原创训练题</td><td>若坚持只读，至少提供“自检清单/章节完成度”与人工错题记录模板</td></tr><tr><td>P2</td><td>版本治理</td><td>核查日期、公告适用对象、地方过渡条款</td><td><code>/exam-guide.md</code>、<code>/sources.md</code>、<code>/training-labels.md</code></td><td>核查日期已更新为2026-08-21；第二批标准日期和适用范围已补，考试公告仍须按报考地当批次复核</td><td><code>/sources.md</code> 增版本变更表</td><td>版本判断题需显示发布日期和核查日期</td><td>官方公告/标准状态待持续复核</td><td>过期时应标“需复核”，不将历史地方口径外推全国</td></tr></tbody></table><h2 id="第七批-理论—技能逐项关联审查表" tabindex="-1">第七批：理论—技能逐项关联审查表 <a class="header-anchor" href="#第七批-理论—技能逐项关联审查表" aria-label="Permalink to &quot;第七批：理论—技能逐项关联审查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>理论章节</th><th>设备原理证据</th><th>操作/保养/维修/检测关联</th><th>训练题编号</th><th>当前覆盖判断</th><th>不会时回看</th><th>进入下一阶段条件</th></tr></thead><tbody><tr><td>1. 职业道德</td><td>记录、复核、报告形成可追溯证据</td><td>四项技能共同记录闭环</td><td>T01、T15、T28；S01、S06、S23</td><td>已建立关联</td><td>理论 1 章、course-companion 学习表</td><td>能区分事实、判断、结论和报告</td></tr><tr><td>2. 消防工作概述</td><td>单位责任与设施可用性</td><td>操作协同、保养交接、维修升级、检测责任</td><td>T02、T16、T29；S01、S25</td><td>已建立关联</td><td>理论 2 章、standard-mapping</td><td>能说清责任对象和升级条件</td></tr><tr><td>3. 燃烧和火灾</td><td>燃烧、烟气、灭火介质边界</td><td>初起操作、器材保养、故障环境判断、检测安全</td><td>T03-T04、T30、T34；S06、S25、S43</td><td>已建立关联</td><td>理论 3 章、设备项目卡</td><td>能把燃烧原理用于安全处置</td></tr><tr><td>4. 建筑防火</td><td>防火分区、防烟分区、防火间距、耐火极限、耐火等级、疏散与防火分隔</td><td>风阀/卷帘/门操作保养维修检测</td><td>T20-T21、T31、T38-T39；S21、S38-S39、S46</td><td>已建立关联，新增五个核心概念的零基础解释与等级辨析</td><td>理论 4 章、其他设施项目卡、综合学习课</td><td>能说明设备保护区域，并区分构件性能时间和建筑整体等级</td></tr><tr><td>5. 电气消防</td><td>主备电、线路、接地、保护</td><td>控制柜操作、接线保养、电气维修、测量检测</td><td>T06、T22、T32；S08、S26、S30、S47</td><td>已建立关联</td><td>理论 5 章、报警项目卡、检测页</td><td>能先区分供电/线路/本体并说出隔离边界</td></tr><tr><td>6. 消防设施</td><td>探测—报警—控制—动作—反馈—恢复</td><td>三类系统四项技能全链路</td><td>T08-T10、T23-T24、T33；S02、S19-S22、S26-S49</td><td>已建立关联</td><td>理论 6 章、course-companion</td><td>能完整复述一条信号链</td></tr><tr><td>7. 初起火灾处置</td><td>报警、疏散、现场保护、复燃</td><td>监控操作、联动安全、停用防护、检测清场</td><td>T07、T11、T17、T34；S01、S21、S25</td><td>已建立关联</td><td>理论 7 章、安全健康</td><td>能把人员安全置于设备操作之前</td></tr><tr><td>8. 计算机基础</td><td>控制器界面、日志、通信</td><td>查询记录、信息故障维修、检测留痕</td><td>T13、T18、T25、T35；S01、S07、S09、S31</td><td>已建立关联</td><td>理论 8 章、监控页</td><td>能从时间/地址/日志追溯现场证据</td></tr><tr><td>9. 法律法规与技术标准</td><td>依据、版本、权限、判定边界</td><td>四项技能的方法和结论依据</td><td>T05、T12、T26、T36；S04、S05、S11-S14</td><td>已建立关联</td><td>理论 9 章、standard-mapping</td><td>能先选依据，再写方法和边界</td></tr><tr><td>10. 安全生产与职业健康</td><td>断电、验电、隔离、监护、清场</td><td>四项技能前置、过程、复原</td><td>T14、T19、T27、T37；S04、S07-S10、S12、S21</td><td>已建立关联</td><td>理论 10 章、项目卡安全边界</td><td>能说出停止条件、临时防护和恢复要求</td></tr></tbody></table><blockquote><p>覆盖表示已有可读学习入口和题号关联，不表示官方题库数量、标准原文逐条核验或鉴定站评分点全部覆盖。</p></blockquote><h3 id="综合复习路径" tabindex="-1">综合复习路径 <a class="header-anchor" href="#综合复习路径" aria-label="Permalink to &quot;综合复习路径&quot;">​</a></h3><ol><li>十章理论逐章复习：每章完成一条“原理→设备行为→安全/记录”的因果句；</li><li>三类设备横向复习：报警、水系统、其他设施分别完成组成、动作、反馈、故障、恢复；</li><li>四项技能纵向复习：对同一设备依次复述操作、保养、维修、检测，并标出各自证据字段；</li><li>综合场景复习：使用 S23-S25，再按薄弱设备回看 S26-S49；</li><li>依据收口复习：对数值、时间、误差、权限和评分点逐项标记来源状态，未核验的保持边界表述。</li></ol><h2 id="推荐落地顺序" tabindex="-1">推荐落地顺序 <a class="header-anchor" href="#推荐落地顺序" aria-label="Permalink to &quot;推荐落地顺序&quot;">​</a></h2><ol><li>继续按国家职业标准和知识点 ID 检查检测维修保养方向四项职业功能，后台映射服务于课程查漏，不替代学习页面。</li><li>按设备项目补技能卡与 L1/L2/L3 题卡，优先报警主机、探测器/模块、主备电、泵组/水系统、风机风阀、卷帘和检测记录。</li><li>为理论十章建立最低题量和知识点覆盖表，补建筑、电气、设施、法规、安全高频缺口。</li><li>逐条核验来源 URL、标准版本和地方公告；修复疑似失效链接，并持续使用“完整知识框架”而不是“官方考试全覆盖”作为站点宣传口径。</li><li>最后统一首页、路线图、训练页的方向口径，并提供人工错题/章节完成度记录。</li></ol>',15)])])}const T=d(c,[["render",a]]);export{S as __pageData,T as default};
